    14  pub(crate) fn generics(interner: DbInterner<'_>, def: SolverDefId) -> Generics<'_> {
    15      let db = interner.db;
    16      let (def, consider_late_bound) = match (def.try_into(), def) {
    17          (Ok(def), _) => (def, false),
    18          (_, SolverDefId::InternedOpaqueTyId(id)) => match id.loc(db) {
    19              crate::ImplTraitId::ReturnTypeImplTrait(function_id, _) => (function_id.into(), true),
    20              crate::ImplTraitId::TypeAliasImplTrait(type_alias_id, _) => {
    21                  (type_alias_id.into(), true)
    22              }
    23          },
    24          (_, SolverDefId::BuiltinDeriveImplId(id)) => {
    25              return crate::builtin_derive::generics_of(interner, id);
    26          }
    27          (_, SolverDefId::AnonConstId(id)) => {
    28              let loc = id.loc(db);
    29              let generic_def = loc.owner.generic_def(db);
    30              return if loc.allow_using_generic_params {
    31                  Generics::from_generic_def(db, generic_def, false)
    32              } else {
    33                  #[expect(
    34                      deprecated,
    35                      reason = "`Generics` only exposes an iterator over `GenericParamId`, \
    36                          so you cannot exploit the erroneous `crate::generics::Generics`"
    37                  )]
    38                  Generics {
    39                      generics: crate::generics::Generics::empty(generic_def),
    40                      additional_param: None,
    41                      consider_late_bound: false,
    42                  }
    43              };
    44          }
    45          _ => panic!("No generics for {def:?}"),
    46      };
    47  
    48      Generics::from_generic_def(db, def, consider_late_bound)
    49  }
    50  
    51  #[derive(Debug)]
    52  pub struct Generics<'db> {
    53      generics: crate::generics::Generics<'db>,
    54      /// This is used for builtin derives, specifically `CoercePointee`.
    55      additional_param: Option<GenericParamId>,
    56      consider_late_bound: bool,
    57  }
    58  
    59  impl<'db> Generics<'db> {
    60      pub(crate) fn from_generic_def(
    61          db: &'db dyn HirDatabase,
    62          def: GenericDefId,
    63          consider_late_bound: bool,
    64      ) -> Generics<'db> {
    65          Generics {
    66              generics: crate::generics::generics(db, def),
    67              additional_param: None,
    68              consider_late_bound,
    69          }
    70      }
